import java.util.*;

public class Main {
    static double sum(List<? extends Number> xs) {
        double r = 0;
        for (Number x : xs) r += x.doubleValue();
        return r;
    }

    public static void main(String[] args) {
        System.out.println(sum(List.of(1, 2, 3)));
    }
}

